var o=[{title:`Sintomas de emergência`,text:`Pare de fazer exercício de imediato se tiver dor ou pressão no peito, desmaiar, ficar com falta de ar intensa sem motivo claro, sentir fraqueza súbita de um lado, tiver uma dor de cabeça intensa e nova com alterações neurológicas ou se desenvolver rapidamente uma reação grave. Um desconforto no peito com suor, náuseas, tonturas ou dor que se espalha para o braço ou a mandíbula precisa dos serviços de emergência.`},{title:`Outros sinais de alerta graves`,text:`Não treine com uma dor súbita e intensa numa articulação ou nas costas, inchaço marcado depois de uma lesão, incapacidade de apoiar o peso, fraqueza que está a piorar ou dormência nova. Dor nas costas acompanhada de perda de controlo da bexiga ou do intestino ou de dormência na zona da virilha precisa de avaliação de emergência de imediato.`},{title:`O que fazer`,text:`Pare, torne a zona segura e peça ajuda. Ligue para o número de emergência local em caso de sintomas de emergência e não conduza se puder estar gravemente doente ou ferido. Se for o parceiro de treino, não tente descobrir a causa e não incentive a pessoa a terminar a série. O TrainUp não consegue avaliar uma emergência, diagnosticar doenças nem substituir um profissional qualificado.`},{title:`A prevenção tem limites`,text:`Os aquecimentos, as cargas sensatas e a progressão gradual podem reduzir o stress evitável, mas não conseguem excluir todos os problemas médicos. Se tiver doença cardíaca conhecida ou fatores de risco importantes, pode precisar de aconselhamento pessoal do seu médico antes de começar um exercício vigoroso.`}];var s=[{label:`NHS: dor no peito e sintomas de emergência`,url:`https://www.nhs.uk/symptoms/chest-pain/`},{label:`NHS: dor lombar e sinais de alerta urgentes`,url:`https://www.nhs.uk/conditions/back-pain/`},{label:`NHS: dor nas articulações`,url:`https://www.nhs.uk/symptoms/joint-pain/`}];var r={sections:o,sources:s};export{r as default,o as sections,s as sources};